fn solve(n: i8, k: i8) -> Vec<i8> {
    // Number of unselected items
    let unselected = n - k;

    // If nothing is selected or everything is selected,
    // there cannot be any “good” unselected items.
    if k == 0 || k == n {
        return vec![0, 0];
    }

    // Otherwise at least one good unselected item is possible,
    // and at most `min(unselected, 2*k)` good unselected items.
    // We use saturating_mul to avoid overflow when computing 2*k.
    let x_min = 1;
    let x_max = unselected.min(k.saturating_mul(2));

    vec![x_min, x_max]
}

